import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const m=JSON.parse('{"title":"1CRM","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/1crm.md","filePath":"integrations/crm/1crm.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/1crm.md"};function a(l,t,s,c,h,g){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_1crm" tabindex="-1">1CRM <a class="header-anchor" href="#_1crm" aria-label="Permalink to &quot;1CRM&quot;">​</a></h1><p>Follow the below steps to connect to the 1CRM API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select 1CRM as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-1crm-api" tabindex="-1">Step 2. Connect to the 1CRM API <a class="header-anchor" href="#step-2-connect-to-the-1crm-api" aria-label="Permalink to &quot;Step 2. Connect to the 1CRM API&quot;">​</a></h3><ol><li>Go to <a href="https://1crm.com" target="_blank">1CRM</a> and login to your account.</li><li>Click on the <strong>Admin</strong> dropdown on the top-right of the screen, and select <strong>Administration</strong>.</li><li>Click the <strong>API Clients</strong> link.</li><li>Click the <strong>Create</strong> button.</li><li>Select <strong>Authorization Code</strong> for the <strong>Enabled Grant Types</strong>.</li><li>Copy the <strong>ID</strong> from 1CRM and paste in the <strong>Client ID</strong> field in Formie.</li><li>Click the <strong>Change API Secret</strong> button and enter a value.</li><li>Copy the <strong>Secret</strong> from 1CRM and paste in the <strong>Client Secret</strong> field in Formie.</li><li>In the <strong>Redirect URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to 1CRM, where you must approve Formie to access your 1CRM account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(i,[["render",a]]);export{m as __pageData,p as default};
